(SELECT COALESCE(sm.disc,0),sm.track FROM c JOIN song_masters sm ON sm.id=c.master_id WHERE sm.track IS NOT NULL GROUP BY COALESCE(sm.disc,0),sm.track HAVING COUNT(*)>1)) AS duplicate_disc_track_groups,(SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-37aa23d328ca4fe29e0e172ff55c7eda' AND sm.album_id!='pending-uploads') AS other_album_members,(SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-37aa23d328ca4fe29e0e172ff55c7eda' AND sm.album_id!='pending-uploads' AND sm.id NOT IN ('')) AS unallowlisted_other_members,(SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE sm.id IN ('') AND sm.album_id IN ('') AND se.source_id='r2-local' AND se.parent_id='se-37aa23d328ca4fe29e0e172ff55c7eda' AND lower(si.suffix)='wav') AS allowlisted_other_members;
